function maxProduct(n) {
  const digits = String(n).split('').map(Number);
  let best = -1;
  for (let i = 0; i < digits.length; i++)
    for (let j = i + 1; j < digits.length; j++)
      best = Math.max(best, digits[i] * digits[j]);
  return best;
}

