function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (rand() < 0.05) return [1000000000];
  const length = size === 'large' ? int(8, 9) : int(2, 9);
  // Capping the digits varies the answer from 0 up to 81.
  const top = int(0, 9);
  let text = String(int(1, Math.max(1, top)));
  while (text.length < length) text += String(int(0, top));
  return [Number(text)];
}
